assert.equal(c.timelineIsPrevious(p,{snapshot:{timeline:{...repeated.snapshot.timeline,approval:{}}}}),true,'old approval fallback');
assert.equal(c.timelineIsPrevious(p,{snapshot:{timeline:{...repeated.snapshot.timeline,approval:{selected_take_snapshot:{}}}}}),true,'invalid capture fails closed');
