remove(1);assert.equal(c.draft.clips.length,1);assert.equal(c.draft.subtitles[0].text,'보존');remove(0);assert.equal(c.draft.clips.length,1);
node('#addClip').onclick();assert.equal(c.draft.clips.length,2);assert.equal(c.draft.clips[1].shot,'s');
while(c.draft.clips.length<30)node('#addClip').onclick();node('#addClip').onclick();assert.equal(c.draft.clips.length,30);
console.log('draft confirmation, saved edit, output snapshot, clip min/max: passed');
const root={inert:false,setAttribute(k,v){this[k]=v}},add={disabled:false},select={options:[{}]},removeButton={disabled:false};
c.document={querySelector:s=>({'.timeline':root,'#addClip':add,'#addClipShot':select}[s]||null),querySelectorAll:s=>s==='#clips [data-remove-clip]'?[removeButton]:[]};
vm.runInContext(block('function updateTimelineControls(', 'function updateRecovery('),c);
c.draft.clips.length=1;c.updateTimelineControls(false);assert.equal(root.inert,false);assert.equal(removeButton.disabled,true);assert.equal(add.disabled,false);
